"""sklearn.utils.graph — graph-traversal helpers."""

import numpy as _np


def single_source_shortest_path_length(graph, source, *, cutoff=None):
    """BFS shortest paths from ``source``. ``graph`` is an adjacency
    matrix or scipy sparse matrix; returns ``{node: distance}``."""
    g = graph if hasattr(graph, 'toarray') else _np.asarray(graph)
    if hasattr(g, 'toarray'): g = g.toarray()
    n = g.shape[0]
    dist = {source: 0}
    frontier = [source]
    while frontier:
        next_frontier = []
        for node in frontier:
            for j in range(n):
                if g[node, j] > 0 and j not in dist:
                    dist[j] = dist[node] + 1
                    if cutoff is None or dist[j] < cutoff:
                        next_frontier.append(j)
        frontier = next_frontier
    return dist
